import { calculateNutrition, consolidate, formatQuantity, generateDay, generateWeek, weightToGrams } from './core.js';
document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" href="/phase1.css">');
let state, view='planner', selectedDay='Monday', recipeFilter='all', recipeSearch='', weekStart=startOfWeek(new Date());
const app=document.querySelector('#app'),days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],short=['MON','TUE','WED','THU','FRI','SAT','SUN'];
const themeButton=document.querySelector('[data-theme-toggle]');function syncTheme(){const dark=document.documentElement.dataset.theme==='dark';themeButton.querySelector('span').textContent=dark?'☀':'☾';themeButton.querySelector('b').textContent=dark?'Light':'Dark';themeButton.setAttribute('aria-pressed',String(dark));document.querySelector('meta[name="theme-color"]').content=dark?'#111713':'#f5f2ea'}syncTheme();themeButton.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('savorly-theme',next);syncTheme()};
function startOfWeek(value){const d=new Date(value);d.setHours(12,0,0,0);const delta=(d.getDay()+6)%7;d.setDate(d.getDate()-delta);return d}function weekKey(){return weekStart.toISOString().slice(0,10)}function weekDates(){return days.map((_,i)=>{const d=new Date(weekStart);d.setDate(d.getDate()+i);return d})}function weekLabel(){const all=weekDates(),fmt=d=>d.toLocaleDateString(undefined,{month:'short',day:'numeric'});return `${fmt(all[0])} – ${fmt(all[6])}`}
async function load(){const r=await fetch('/api/state');if(!r.ok)throw Error();state=await r.json();state.customRecipes??=[];state.reviews=new Proxy(state.reviews||{},{set(target,key,value){target[key]={...target[key],...value};return true}});state.preferences??={maxSlots:4,highProtein:true,batchFirst:true};state.preferences.maxSlots??=4;state.extras={weekPlans:{},pantry:[],inventory:{},manualShopping:[],diet:{dislikes:'',allergies:'',style:'Anything',maxTime:120,proteins:''},mealHistory:[],...(state.extras||{})};if(Object.keys(state.extras.weekPlans).length===0)state.extras.weekPlans[weekKey()]=state.plan;else state.plan=state.extras.weekPlans[weekKey()]||[];render()}
async function save(message='Saved'){state.extras.weekPlans[weekKey()]=state.plan;const r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({goals:state.goals,plan:state.plan,checked:state.checked,customRecipes:state.customRecipes,reviews:state.reviews,preferences:state.preferences,extras:state.extras})});if(!r.ok)return toast('Could not save changes');toast(message);renderNav()}
async function apiPayload(response){const type=response.headers.get('content-type')||'';if(!type.includes('application/json'))throw Error(response.status===404?'Recipe search needs the latest server. Restart or rebuild Savorly.':'The provider returned an unexpected response.');return response.json()}
const recipe=id=>state.recipes.find(r=>r.id===id),esc=value=>String(value??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])),fallbackImage='https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=900&q=85',image=r=>`<img src="${esc(r.image||fallbackImage)}" alt="${esc(r.title)}" loading="lazy">`;
function renderNav(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.querySelector('#shopCount').textContent=consolidate(state.plan,state.recipes).length}
function totals(day){return state.plan.filter(m=>m.day===day&&m.status!=='Skipped').reduce((a,m)=>{const r=recipe(m.recipeId);return{cal:a.cal+Math.round(r.calories*m.servings),protein:a.protein+Math.round(r.protein*m.servings)}},{cal:0,protein:0})}
function render(){renderNav();view==='planner'?renderPlanner():view==='recipes'?renderRecipes():renderShopping();enhanceView();enhanceMilestone();if(view==='shopping'&&consolidate(state.plan,state.recipes).length)document.querySelector('.shopping-tools')?.insertAdjacentHTML('afterbegin','<button data-email-list>✉ Email list</button>')}
function dayCard(day){const idx=days.indexOf(day),meals=state.plan.filter(m=>m.day===day),t=totals(day);return `<article class="day-card ${idx>4?'weekend':''}"><div class="day"><div><span>${short[idx]}</span><b>${weekDates()[idx].getDate()}</b></div>${idx>4?'<em>WEEKEND</em>':''}</div><div class="meal-list">${meals.length?meals.map(mealRow).join(''):`<button class="empty-day" data-add data-day="${day}"><span>＋</span><strong>Plan ${day}</strong><small>Add breakfast, lunch or dinner</small></button>`}</div>${meals.length?`<button class="mini-add" data-add data-day="${day}">＋ Add another</button><div class="day-total"><span>${t.cal.toLocaleString()} / ${state.goals.calories.toLocaleString()} kcal</span><span>${t.protein} / ${state.goals.protein}g</span></div>`:''}</article>`}
function mealRow(m){const r=recipe(m.recipeId);return `<div class="meal ${m.status?m.status.toLowerCase():''}">${image(r)}<div><strong>${r.title}</strong><small>${m.slot} · ${Math.round(r.calories*m.servings)} kcal · ${Math.round(r.protein*m.servings)}g</small><span>${m.servings} serving${m.servings===1?'':'s'}${m.status?` · ${m.status}`:''}</span></div><button data-meal-status="${m.id}" aria-label="Update meal status">${m.status==='Eaten'?'✓':'○'}</button><button data-swap="${m.id}" aria-label="Swap ${r.title}">↻</button><button data-remove="${m.id}" aria-label="Remove ${r.title}">×</button></div>`}
function recipeCard(r){const review=state.reviews[r.id]||{},used=state.plan.filter(m=>m.recipeId===r.id).reduce((n,m)=>n+m.servings,0),remaining=r.batch?Math.max(0,r.servings-used):null,needsReview=r.imported&&!r.nutritionReady,nutrition=!needsReview&&(r.calories||r.protein)?`${r.calories} kcal · ${r.protein}g protein per serving`:'Nutrition check needed';return `<article class="${r.batch?'batch-recipe':''} ${review.excluded?'excluded-recipe':''}">${image(r)}<div>${r.batch?`<mark>ONE POT · ${esc(r.batchDays).toUpperCase()}</mark>`:''}${r.custom?'<mark class="personal">MY RECIPE</mark>':''}${r.imported?'<mark class="provider">THEMEALDB</mark>':''}<span>${r.time} MIN · ${esc(r.difficulty).toUpperCase()}</span><h3>${esc(r.title)}</h3><p>${nutrition}</p><small class="yield">${r.batch?`${remaining} of ${r.servings} portions unplanned`: `Makes ${r.servings} servings`} ${review.status?`· ${esc(review.status)}`:''}</small>${review.rating?`<div class="card-rating" aria-label="${review.rating} stars">${'★'.repeat(review.rating)}${'☆'.repeat(5-review.rating)}</div>`:''}<div class="preference-actions"><button data-favorite="${r.id}" class="${review.favorite?'selected':''}">♥ ${review.favorite?'Favorite':'Favorite'}</button><button data-exclude="${r.id}" class="${review.excluded?'selected':''}">${review.excluded?'✓ Excluded':'⊘ Don’t suggest'}</button></div><div class="card-actions"><button data-detail="${r.id}">View recipe</button><button data-pick="${r.id}" ${needsReview?'disabled title="Complete nutrition before planning"':''}>＋ Plan</button></div></div></article>`}
function renderPlanner(){const planned=state.plan.length;app.innerHTML=`<section class="intro"><div><p class="eyebrow">WEEK OF SEPTEMBER 7</p><h1>Good food, thoughtfully planned.</h1><p>${planned?`${planned} meal${planned===1?'':'s'} planned. Your week is taking shape.`:'Build a week that fits your life and your goals.'}</p></div><button class="primary" data-add>＋ Add meal</button></section><section class="goal-card"><div><p>Daily goals</p><strong>${state.goals.calories.toLocaleString()} <small>kcal</small></strong><span>•</span><strong>${state.goals.protein} <small>g protein</small></strong></div><button data-goals>Edit goals</button></section><section class="week seven">${days.map(dayCard).join('')}</section><section class="lower"><div><div class="section-head"><div><p class="eyebrow">DISCOVER</p><h2>Recipes for your week</h2></div><button data-viewlink="recipes">View all →</button></div><div class="recipes">${state.recipes.slice(0,3).map(recipeCard).join('')}</div></div><aside><p class="eyebrow">THIS WEEK</p><h2>Your shopping list</h2><div class="shop-stat"><strong>${consolidate(state.plan,state.recipes).length}</strong><span>ingredients<br>across ${new Set(state.plan.map(m=>m.recipeId)).size} recipes</span></div><button class="primary" data-viewlink="shopping">View shopping list</button><small>Everything grouped by aisle, automatically.</small></aside></section>`;bind()}
function renderRecipes(){const shown=recipeFilter==='batch'?state.recipes.filter(r=>r.batch):recipeFilter==='mine'?state.recipes.filter(r=>r.custom):state.recipes;app.innerHTML=`<section class="intro"><div><p class="eyebrow">RECIPE LIBRARY</p><h1>Your kitchen, your favorites.</h1><p>Save recipes, record what worked, and build a library you trust.</p></div><button class="primary" data-new-recipe>＋ New recipe</button></section><section class="batch-banner"><div><p class="eyebrow">COOK ONCE, EAT ALL WEEK</p><h2>One-pot batch meals</h2><p>Six to eight servings and minimal cleanup. Refrigerate 3–4 days and freeze later portions.</p></div><button data-filter="batch">Explore batch meals →</button></section><div class="filter-row"><div><button data-filter="all" class="${recipeFilter==='all'?'active':''}">All recipes</button><button data-filter="batch" class="${recipeFilter==='batch'?'active':''}">One-pot batches</button><button data-filter="mine" class="${recipeFilter==='mine'?'active':''}">My recipes</button></div><span>${shown.length} recipes</span></div>${shown.length?`<section class="recipes full">${shown.map(recipeCard).join('')}</section>`:`<section class="empty-state small"><h2>Your recipe box is ready.</h2><p>Add your first personal recipe, including its ingredients, method, and nutrition.</p><button class="primary" data-new-recipe>Add a recipe</button></section>`}<section class="quality-note"><div><span>✓</span><div><p class="eyebrow">SAVORLY RECIPE STANDARD</p><h2>Good recipes earn their place.</h2></div></div><p>Move a recipe from Draft to Tried, then Verified after you have cooked, timed, portioned, and adjusted it to your taste.</p><ol><li>Reliable ingredient ratios and clear instructions</li><li>Nutrition calculated per serving</li><li>Realistic prep time and storage guidance</li><li>Your rating and cooking notes</li></ol></section>`;bind()}
function renderShopping(){const list=consolidate(state.plan,state.recipes),groups=list.reduce((a,x)=>((a[x.aisle]??=[]).push(x),a),{}),checked=state.checked||[];app.innerHTML=`<section class="intro shopping-head"><div><p class="eyebrow">SHOPPING LIST</p><h1>One trip. Everything you need.</h1><p>Automatically combined and scaled from this week's plan.</p></div>${list.length?'<button class="outline" data-clearchecks>Clear checks</button>':''}</section>${list.length?`<section class="shopping-layout"><div class="aisles">${Object.entries(groups).map(([aisle,items])=>`<article><h2>${aisle}<span>${items.length}</span></h2>${items.map(i=>`<label class="shop-item ${checked.includes(i.key)?'done':''}"><input type="checkbox" data-check="${i.key}" ${checked.includes(i.key)?'checked':''}><span></span><strong>${formatQuantity(i.quantity)} ${i.unit}</strong><div>${i.name}<small>${i.recipes.join(', ')}</small></div></label>`).join('')}</article>`).join('')}</div><aside class="list-note"><p class="eyebrow">READY TO SHOP</p><strong>${checked.length} of ${list.length}</strong><span>items checked</span><div class="progress"><i style="width:${list.length?checked.length/list.length*100:0}%"></i></div><small>Serving changes in your planner are reflected here automatically.</small></aside></section>`:`<section class="empty-state"><span>☘</span><h2>Your list is waiting.</h2><p>Add a few recipes to your week and every ingredient will appear here, combined by aisle.</p><button class="primary" data-viewlink="recipes">Browse recipes</button></section>`}`;bind()}
function bind(){document.querySelectorAll('[data-viewlink]').forEach(b=>b.onclick=()=>switchView(b.dataset.viewlink));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{recipeFilter=b.dataset.filter;renderRecipes()});document.querySelectorAll('[data-new-recipe]').forEach(b=>b.onclick=()=>openRecipeForm());document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openRecipeDetail(b.dataset.detail));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openPicker(b.dataset.day));document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>openSchedule(b.dataset.pick));document.querySelector('[data-goals]')?.addEventListener('click',openGoals);document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=async()=>{state.plan=state.plan.filter(m=>m.id!==b.dataset.remove);await save('Meal removed');render()});document.querySelectorAll('[data-check]').forEach(c=>c.onchange=async()=>{state.checked=c.checked?[...new Set([...state.checked,c.dataset.check])]:state.checked.filter(x=>x!==c.dataset.check);await save();renderShopping()});document.querySelector('[data-clearchecks]')?.addEventListener('click',async()=>{state.checked=[];await save('Checks cleared');renderShopping()})}
function switchView(next){view=next;render();scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
function modal(html){document.querySelector('#modalBody').innerHTML=html;document.querySelector('#modal').hidden=false;document.body.classList.add('locked');document.querySelector('.dialog input,.dialog select,.dialog button')?.focus()}
function close(){document.querySelector('#modal').hidden=true;document.body.classList.remove('locked')}document.querySelectorAll('[data-close]').forEach(x=>x.onclick=close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
function openGoals(){modal(`<p class="eyebrow">PERSONAL TARGETS</p><h2 id="modalTitle">Set daily goals</h2><p class="dialog-copy">We'll show your progress against these targets on each day.</p><form id="goalForm"><label>Calories per day<input name="calories" type="number" min="800" max="6000" step="50" value="${state.goals.calories}" required></label><label>Protein per day <small>(grams)</small><input name="protein" type="number" min="20" max="500" step="5" value="${state.goals.protein}" required></label><button class="primary">Save goals</button></form>`);document.querySelector('#goalForm').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);state.goals={calories:Number(d.get('calories')),protein:Number(d.get('protein'))};close();await save('Goals updated');render()}}
function openPicker(day=selectedDay){selectedDay=day||'Monday';modal(`<p class="eyebrow">ADD A MEAL</p><h2 id="modalTitle">Choose a recipe</h2><p class="dialog-copy">Adding to <strong>${selectedDay}</strong>. You can adjust the details next.</p><div class="picker">${state.recipes.map(r=>`<button data-modal-recipe="${r.id}">${image(r)}<span><strong>${r.title}</strong><small>${r.calories} kcal · ${r.protein}g protein</small></span><b>＋</b></button>`).join('')}</div>`);document.querySelectorAll('[data-modal-recipe]').forEach(b=>b.onclick=()=>openSchedule(b.dataset.modalRecipe,selectedDay))}
function openSchedule(id,day=selectedDay){const r=recipe(id);modal(`<p class="eyebrow">PLAN THIS RECIPE</p><h2 id="modalTitle">${r.title}</h2>${r.batch?`<p class="batch-tip">This pot makes ${r.servings} servings—enough for ${r.batchDays}. Plan the portions you expect to eat on this day.</p>`:''}<form id="scheduleForm"><label>Day<select name="day">${days.map(d=>`<option ${d===day?'selected':''}>${d}</option>`).join('')}</select></label><label>Meal<select name="slot"><option>Breakfast</option><option selected>Lunch</option><option>Dinner</option></select></label><label>Portions for this day<input name="servings" type="number" min="1" max="12" value="${r.batch?1:r.servings}" required></label><div class="nutrition-note">Per serving <strong>${r.calories} kcal</strong><strong>${r.protein}g protein</strong></div><button class="primary">Add to week</button></form>`);document.querySelector('#scheduleForm').onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target);state.plan.push({id:crypto.randomUUID(),recipeId:r.id,day:d.get('day'),slot:d.get('slot'),servings:Number(d.get('servings'))});close();view='planner';await save('Meal added to your week');render()}}
function openRecipeDetail(id){const r=recipe(id),review=state.reviews[id]||{status:'Draft',rating:0,notes:''};modal(`<div class="recipe-detail">${image(r)}<div class="detail-title"><div><p class="eyebrow">${r.imported?'IMPORTED FROM THEMEALDB':r.custom?'MY RECIPE':'TEST KITCHEN DRAFT'}</p><h2 id="modalTitle">${esc(r.title)}</h2><p>${r.time} min · ${r.calories||'—'} kcal · ${r.protein||'—'}g protein per serving</p></div>${r.custom?'<button class="outline" data-edit-recipe>Edit</button>':''}</div>${r.imported&&!r.nutritionReady?'<div class="draft-warning nutrition-callout"><span>This source does not include nutrition. Review every ingredient before planning it.</span><button class="primary" data-complete-nutrition>Complete nutrition</button></div>':''}<div class="detail-columns"><section><h3>Ingredients</h3><p class="makes">Makes ${r.servings} servings</p><ul>${r.ingredients.map(i=>`<li><strong>${esc(i.quantity)} ${esc(i.unit)}</strong> ${esc(i.name)}</li>`).join('')}</ul><h3>Storage</h3><p>${esc(r.storage||'Cool promptly. Refrigerate for up to 3–4 days or freeze extra portions.')}</p>${r.sourceUrl?`<p><a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener">Original recipe at ${esc(r.sourceName||'source')} ↗</a></p>`:''}</section><section><h3>Method</h3>${r.instructions?.length?`<ol>${r.instructions.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:'<div class="draft-warning">Cooking instructions for this starter concept have not been kitchen-tested yet. Add your own version before marking it Verified.</div>'}<div class="review-box"><h3>Your verdict</h3><div class="stars" aria-label="Recipe rating">${[1,2,3,4,5].map(n=>`<button type="button" data-star="${n}" class="${n<=review.rating?'on':''}" aria-label="${n} stars">★</button>`).join('')}</div><label>Status<select id="recipeStatus"><option ${review.status==='Draft'?'selected':''}>Draft</option><option ${review.status==='Tried'?'selected':''}>Tried</option><option ${review.status==='Verified'?'selected':''}>Verified</option></select></label><label>Cooking notes<textarea id="recipeNotes" placeholder="What would you change next time?">${esc(review.notes)}</textarea></label><button class="primary" data-save-review>Save verdict</button></div></section></div>${r.custom?'<button class="danger" data-delete-recipe>Delete recipe</button>':''}</div>`);let rating=review.rating;document.querySelectorAll('[data-star]').forEach(b=>b.onclick=()=>{rating=Number(b.dataset.star);document.querySelectorAll('[data-star]').forEach(x=>x.classList.toggle('on',Number(x.dataset.star)<=rating))});document.querySelector('[data-complete-nutrition]')?.addEventListener('click',()=>openNutritionReview(r));document.querySelector('[data-save-review]').onclick=async()=>{state.reviews[id]={...review,rating,status:document.querySelector('#recipeStatus').value,notes:document.querySelector('#recipeNotes').value};close();await save('Recipe verdict saved');renderRecipes()};document.querySelector('[data-edit-recipe]')?.addEventListener('click',()=>openRecipeForm(r));document.querySelector('[data-delete-recipe]')?.addEventListener('click',async()=>{if(!confirm(`Delete ${r.title}? This cannot be undone.`))return;state.customRecipes=state.customRecipes.filter(x=>x.id!==id);state.recipes=state.recipes.filter(x=>x.id!==id);state.plan=state.plan.filter(x=>x.recipeId!==id);delete state.reviews[id];close();await save('Recipe deleted');renderRecipes()})}
function enhanceView(){if(view==='planner'&&!document.querySelector('[data-build-week]'))document.querySelector('.intro>.primary')?.insertAdjacentHTML('beforebegin','<button class="smart-button" data-build-week>✦ Build my week</button>');document.querySelector('[data-build-week]')?.addEventListener('click',openSmartPlanner);if(view==='planner')document.querySelectorAll('.day-card').forEach((card,index)=>{const t=totals(days[index]),calGap=state.goals.calories-t.cal,proteinGap=state.goals.protein-t.protein,status=proteinGap<=3&&Math.abs(calGap)<=state.goals.calories*.08?'on target':`${proteinGap>0?`${proteinGap}g protein left`:'protein met'} · ${calGap>0?`${calGap} kcal left`:`${Math.abs(calGap)} kcal over`}`;card.insertAdjacentHTML('beforeend',`<div class="goal-gap ${proteinGap<=3?'met':''}"><span>${status}</span><button data-fix-day="${days[index]}">Fix this day</button></div>`)})}
function openSmartPlanner(){const p=state.preferences;modal(`<p class="eyebrow">GOAL-AWARE WEEK</p><h2 id="modalTitle">Build a week around your targets</h2><p class="dialog-copy">Savorly can add snacks and half portions when three meals do not reasonably reach ${state.goals.protein}g protein within ${state.goals.calories.toLocaleString()} calories.</p><form id="smartForm"><label>Maximum eating slots per day<select name="slots"><option value="3" ${p.maxSlots===3?'selected':''}>3 slots</option><option value="4" ${(!p.maxSlots||p.maxSlots===4)?'selected':''}>4 slots</option><option value="5" ${p.maxSlots===5?'selected':''}>5 slots</option><option value="6" ${p.maxSlots===6?'selected':''}>6 slots</option></select></label><label class="toggle-row"><input name="protein" type="checkbox" ${p.highProtein?'checked':''}> Prioritize protein-efficient choices</label><label class="toggle-row"><input name="batch" type="checkbox" ${p.batchFirst?'checked':''}> Use batch meals first</label><div class="generator-note">Targets are flexible: calories aim within roughly ±8%, while protein aims to meet or slightly exceed your goal. Your current plan stays unchanged until approval.</div><button class="primary">Create goal-aware proposal</button></form>`);document.querySelector('#smartForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.preferences={maxSlots:Number(d.get('slots')),highProtein:d.has('protein'),batchFirst:d.has('batch')};showProposal(generateWeek(state.recipes,state.reviews,state.preferences,state.goals))}}
function showProposal(proposal){if(!proposal.length)return toast('All recipes are excluded—allow at least one recipe');modal(`<p class="eyebrow">YOUR GOAL-AWARE WEEK</p><h2 id="modalTitle">A realistic starting point</h2><p class="dialog-copy">Half portions and snacks are used where they make the calorie-to-protein balance more practical.</p><div class="proposal">${days.map(day=>{const meals=proposal.filter(m=>m.day===day),total=meals.reduce((a,m)=>{const r=recipe(m.recipeId);return{cal:a.cal+r.calories*m.servings,protein:a.protein+r.protein*m.servings}},{cal:0,protein:0}),proteinMet=total.protein>=state.goals.protein*.98,calMet=total.cal>=state.goals.calories*.85&&total.cal<=state.goals.calories*1.08;return `<section class="${proteinMet&&calMet?'on-target':'needs-work'}"><h3>${day}<small>${Math.round(total.cal)} kcal · ${Math.round(total.protein)}g</small></h3>${meals.map(m=>`<div>${image(recipe(m.recipeId))}<span><strong>${esc(recipe(m.recipeId).title)}</strong><small>${m.slot} · ${m.servings} portion${m.servings===1?'':'s'}</small></span></div>`).join('')}<em>${proteinMet&&calMet?'✓ Within target range':'△ Closest available match'}</em></section>`}).join('')}</div><div class="proposal-actions"><button class="outline" data-rethink>Change preferences</button><button class="primary" data-accept-week>Use this week</button></div>`);document.querySelector('[data-rethink]').onclick=openSmartPlanner;document.querySelector('[data-accept-week]').onclick=async()=>{state.plan=proposal.map(m=>({...m,id:crypto.randomUUID()}));close();await save('Your new week is ready');render()}}
document.addEventListener('click',async e=>{const favorite=e.target.closest('[data-favorite]'),exclude=e.target.closest('[data-exclude]'),swap=e.target.closest('[data-swap]');if(favorite){const id=favorite.dataset.favorite;state.reviews[id]={...(state.reviews[id]||{status:'Draft',rating:0,notes:''}),favorite:!state.reviews[id]?.favorite};await save(state.reviews[id].favorite?'Added to favorites':'Removed from favorites');renderRecipes()}if(exclude){const id=exclude.dataset.exclude;state.reviews[id]={...(state.reviews[id]||{status:'Draft',rating:0,notes:''}),excluded:!state.reviews[id]?.excluded};await save(state.reviews[id].excluded?'Recipe will not be suggested':'Recipe can be suggested');renderRecipes()}if(swap){const meal=state.plan.find(m=>m.id===swap.dataset.swap),current=recipe(meal.recipeId),choices=state.recipes.filter(r=>r.id!==current.id&&!state.reviews[r.id]?.excluded).sort((a,b)=>Number(state.reviews[b.id]?.favorite)-Number(state.reviews[a.id]?.favorite)||(state.reviews[b.id]?.rating||0)-(state.reviews[a.id]?.rating||0)||b.protein-a.protein);if(!choices.length)return toast('No alternative recipes available');const prior=Number(meal.swapIndex??-1),next=choices[(prior+1)%choices.length];meal.recipeId=next.id;meal.swapIndex=(prior+1)%choices.length;await save(`Swapped in ${next.title}`);render()}})
document.addEventListener('click',async e=>{const button=e.target.closest('[data-fix-day]');if(!button)return;const day=button.dataset.fixDay,replacement=generateDay(state.recipes,state.reviews,state.preferences,state.goals,day,days.indexOf(day));if(!replacement.length)return toast('No eligible recipes available');state.plan=[...state.plan.filter(m=>m.day!==day),...replacement.map(m=>({...m,id:crypto.randomUUID()}))];await save(`${day} adjusted toward your goals`);render()})
function enhanceMilestone(){if(view==='planner'){const eyebrow=document.querySelector('.intro .eyebrow');if(eyebrow)eyebrow.textContent=`WEEK OF ${weekDates()[0].toLocaleDateString(undefined,{month:'long',day:'numeric'}).toUpperCase()}`;document.querySelector('.intro').insertAdjacentHTML('afterend',`<div class="week-tools"><button data-week="-1">← Previous</button><strong>${weekLabel()}</strong><button data-today>Today</button><button data-copy-week>Copy previous</button><button data-week="1">Next →</button><button data-settings>Preferences & backup</button></div>`);const active=state.plan.filter(m=>m.status!=='Skipped'),eaten=active.filter(m=>m.status==='Eaten'),avg=days.reduce((n,d)=>n+totals(d).protein,0)/7,waste=state.extras.mealHistory.filter(x=>x.status==='Eaten').length;document.querySelector('.week').insertAdjacentHTML('afterend',`<section class="insights"><div><span>PLANNED</span><strong>${active.length}</strong><small>meals this week</small></div><div><span>PROTEIN AVG</span><strong>${Math.round(avg)}g</strong><small>daily planned</small></div><div><span>COMPLETED</span><strong>${eaten.length}</strong><small>meals eaten</small></div><div><span>MEALS SAVED</span><strong>${waste}</strong><small>tracked over time</small></div></section>`)}if(view==='recipes'){document.querySelector('.batch-banner').insertAdjacentHTML('afterend',`<div class="recipe-tools"><input id="recipeSearch" type="search" placeholder="Search your saved recipes…" value="${esc(recipeSearch)}"><button data-online-recipes>Find new recipes</button><button data-settings>Dietary preferences</button></div>`);document.querySelector('[data-online-recipes]').onclick=openOnlineRecipeSearch;const input=document.querySelector('#recipeSearch'),apply=()=>{recipeSearch=input.value.toLowerCase();document.querySelectorAll('.recipes.full>article').forEach(card=>{const id=card.querySelector('[data-detail]')?.dataset.detail,r=recipe(id),diet=state.extras.diet,blocked=(diet.dislikes||'').toLowerCase().split(',').some(x=>x.trim()&&JSON.stringify(r.ingredients).toLowerCase().includes(x.trim())),matches=!recipeSearch||`${r.title} ${r.protein} ${r.ingredients.map(i=>i.name).join(' ')}`.toLowerCase().includes(recipeSearch);card.hidden=!matches||r.time>Number(diet.maxTime||999)||blocked;if(r.batch){const stock=state.extras.inventory[r.id]||0;card.querySelector('.yield')?.insertAdjacentHTML('beforeend',` · <b>${stock} prepared</b>`);card.querySelector('.preference-actions')?.insertAdjacentHTML('beforeend',`<button data-cook-batch="${r.id}">＋ Cook batch</button>`)}})};input.oninput=apply;apply()}if(view==='shopping'){document.querySelector('.shopping-head').insertAdjacentHTML('afterend','<div class="shopping-tools"><button data-add-shopping>＋ Add item</button><button data-print>Print</button><button data-share>Share</button><button data-settings>Pantry & preferences</button></div>');document.querySelectorAll('.shop-item').forEach(label=>{const key=label.querySelector('[data-check]').dataset.check;if(state.extras.pantry.includes(key))label.classList.add('in-pantry');label.insertAdjacentHTML('beforeend',`<button type="button" data-pantry="${key}">${state.extras.pantry.includes(key)?'In pantry':'I have this'}</button>`)});if(state.extras.manualShopping.length)document.querySelector('.aisles')?.insertAdjacentHTML('beforeend',`<article><h2>Added by you<span>${state.extras.manualShopping.length}</span></h2>${state.extras.manualShopping.map(item=>`<label class="shop-item manual"><span></span><div>${esc(item.name)}</div><button data-remove-shopping="${item.id}">×</button></label>`).join('')}</article>`)}}
async function changeWeek(delta){state.extras.weekPlans[weekKey()]=state.plan;weekStart=new Date(weekStart);weekStart.setDate(weekStart.getDate()+delta*7);state.plan=structuredClone(state.extras.weekPlans[weekKey()]||[]);await save();render()}
function openSettings(){const d=state.extras.diet;modal(`<p class="eyebrow">PERSONAL SETTINGS</p><h2 id="modalTitle">Preferences, pantry & backup</h2><form id="settingsForm"><label>Eating style<select name="style"><option ${d.style==='Anything'?'selected':''}>Anything</option><option ${d.style==='Vegetarian'?'selected':''}>Vegetarian</option><option ${d.style==='Pescatarian'?'selected':''}>Pescatarian</option></select></label><label>Maximum recipe time <small>(minutes)</small><input name="maxTime" type="number" min="5" max="300" value="${d.maxTime||120}"></label><label>Allergies <small>(comma separated)</small><input name="allergies" value="${esc(d.allergies)}" placeholder="Peanuts, shellfish"></label><label>Disliked ingredients <small>(comma separated)</small><input name="dislikes" value="${esc(d.dislikes)}" placeholder="Mushrooms, olives"></label><label>Preferred proteins<input name="proteins" value="${esc(d.proteins)}" placeholder="Chicken, turkey, tofu"></label><button class="primary">Save preferences</button></form><div class="backup-box"><h3>Your local data</h3><p>Download a complete backup of recipes, plans, ratings, pantry, and preferences.</p><button class="outline" data-export>Download backup</button><label class="outline upload">Restore backup<input type="file" accept="application/json" data-import></label></div>`);document.querySelector('#settingsForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);state.extras.diet={style:f.get('style'),maxTime:Number(f.get('maxTime')),allergies:f.get('allergies'),dislikes:f.get('dislikes'),proteins:f.get('proteins')};close();await save('Preferences saved');render()};document.querySelector('[data-export]').onclick=exportBackup;document.querySelector('[data-import]').onchange=importBackup}
function exportBackup(){const blob=new Blob([JSON.stringify({...state,recipes:undefined},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`savorly-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href)}
async function importBackup(e){try{const data=JSON.parse(await e.target.files[0].text());if(!data.goals||!data.extras||!Array.isArray(data.customRecipes))throw Error();Object.assign(state,data);state.recipes=[...state.recipes.filter(r=>!r.custom),...state.customRecipes];close();await save('Backup restored');render()}catch{toast('That backup file is not valid')}}
document.addEventListener('click',async e=>{const week=e.target.closest('[data-week]'),today=e.target.closest('[data-today]'),copy=e.target.closest('[data-copy-week]'),settings=e.target.closest('[data-settings]'),status=e.target.closest('[data-meal-status]'),pantry=e.target.closest('[data-pantry]'),cook=e.target.closest('[data-cook-batch]'),addShop=e.target.closest('[data-add-shopping]'),removeShop=e.target.closest('[data-remove-shopping]');if(week)return changeWeek(Number(week.dataset.week));if(today){state.extras.weekPlans[weekKey()]=state.plan;weekStart=startOfWeek(new Date());state.plan=structuredClone(state.extras.weekPlans[weekKey()]||[]);await save();return render()}if(copy){const prior=new Date(weekStart);prior.setDate(prior.getDate()-7);const source=state.extras.weekPlans[prior.toISOString().slice(0,10)]||[];if(!source.length)return toast('The previous week has no meals');state.plan=source.map(m=>({...m,id:crypto.randomUUID(),status:undefined}));await save('Previous week copied');return render()}if(settings)return openSettings();if(status){const meal=state.plan.find(m=>m.id===status.dataset.mealStatus),next=!meal.status?'Eaten':meal.status==='Eaten'?'Skipped':undefined;meal.status=next;if(next)state.extras.mealHistory.push({recipeId:meal.recipeId,status:next,date:new Date().toISOString()});if(next==='Eaten'&&recipe(meal.recipeId).batch)state.extras.inventory[meal.recipeId]=Math.max(0,(state.extras.inventory[meal.recipeId]||0)-meal.servings);await save(next||'Meal reset');return render()}if(pantry){const key=pantry.dataset.pantry;state.extras.pantry=state.extras.pantry.includes(key)?state.extras.pantry.filter(x=>x!==key):[...state.extras.pantry,key];await save('Pantry updated');return renderShopping()}if(cook){const r=recipe(cook.dataset.cookBatch);state.extras.inventory[r.id]=(state.extras.inventory[r.id]||0)+r.servings;await save(`${r.servings} portions added`);return renderRecipes()}if(addShop){const name=prompt('What do you need?')?.trim();if(name){state.extras.manualShopping.push({id:crypto.randomUUID(),name});await save('Shopping item added');renderShopping()}return}if(removeShop){state.extras.manualShopping=state.extras.manualShopping.filter(x=>x.id!==removeShop.dataset.removeShopping);await save('Shopping item removed');return renderShopping()}if(e.target.closest('[data-print]'))return print();if(e.target.closest('[data-share]')){const text=[...document.querySelectorAll('.shop-item:not(.in-pantry)')].map(x=>x.innerText.trim()).join('\n');if(navigator.share)await navigator.share({title:'Savorly shopping list',text});else{await navigator.clipboard.writeText(text);toast('Shopping list copied')}}})
async function emailShoppingList(button){const planned=consolidate(state.plan,state.recipes).filter(item=>!state.checked.includes(item.key)&&!state.extras.pantry.includes(item.key)).map(item=>({aisle:item.aisle,name:item.name,quantity:`${formatQuantity(item.quantity)} ${item.unit}`,recipes:item.recipes})),manual=state.extras.manualShopping.map(item=>({aisle:'Added by you',name:item.name,quantity:'',recipes:[]})),items=[...planned,...manual];if(!items.length)return toast('Everything is already checked or in your pantry');button.disabled=true;button.textContent='Sending…';try{const response=await fetch('/api/shopping/email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({week:weekLabel(),items})}),payload=await apiPayload(response);if(!response.ok)throw Error(payload.error||'Email could not be sent');toast(`Shopping list emailed · ${payload.itemCount} items`)}catch(error){modal(`<p class="eyebrow">EMAIL SHOPPING LIST</p><h2 id="modalTitle">SMTP setup needed</h2><p class="dialog-copy">${esc(error.message)}</p><div class="smtp-help"><p>Add these variables to the Savorly container in Unraid, then select <strong>Apply</strong>:</p><code>SMTP_HOST</code><code>SMTP_PORT</code><code>SMTP_SECURE</code><code>SMTP_USER</code><code>SMTP_PASS</code><code>SMTP_FROM</code><code>SMTP_TO</code><small>Use an app password when your email provider supports one. Port 465 normally uses SMTP_SECURE=true; port 587 normally uses false.</small></div>`) }finally{button.disabled=false;button.textContent='✉ Email list'}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-email-list]');if(button)emailShoppingList(button)});
function openNutritionReview(source){const working=structuredClone(source),reviewed=new Set(working.ingredients.map((item,index)=>item.nutritionReviewed||item.calories||item.protein?index:null).filter(index=>index!==null));let active=working.ingredients.findIndex((_,index)=>!reviewed.has(index));const draw=()=>{const done=reviewed.size,total=working.ingredients.length;modal(`<section class="nutrition-review"><p class="eyebrow">PLANNER-READY CHECK</p><h2 id="modalTitle">Complete ${esc(working.title)}</h2><p class="dialog-copy">Match each ingredient to USDA nutrition. Weight measures convert automatically; for cups or whole items, enter the gram weight you actually use.</p><div class="review-progress"><span style="width:${total?done/total*100:0}%"></span></div><strong class="review-count">${done} of ${total} ingredients reviewed</strong><div class="nutrition-workspace"><div class="nutrition-queue">${working.ingredients.map((item,index)=>`<button type="button" data-review-ingredient="${index}" class="${reviewed.has(index)?'done':''} ${active===index?'active':''}"><i>${reviewed.has(index)?'✓':index+1}</i><span><strong>${esc(item.name)}</strong><small>${esc(item.quantity)} ${esc(item.unit)}${reviewed.has(index)?` · ${item.calories||0} kcal · ${item.protein||0}g`:''}</small></span></button>`).join('')}</div><section class="nutrition-match">${active<0?'<div class="review-complete"><span>✓</span><h3>Every ingredient is reviewed</h3><p>Save to calculate the recipe totals and unlock it for planning.</p></div>':`<h3>${esc(working.ingredients[active].name)}</h3><p class="measure-note">Imported amount: ${esc(working.ingredients[active].quantity)} ${esc(working.ingredients[active].unit)}</p><div class="match-search"><input id="matchQuery" value="${esc(working.ingredients[active].name)}" aria-label="USDA food search"><label>Amount (g)<input id="matchAmount" type="number" min="1" max="10000" value="${weightToGrams(working.ingredients[active].quantity,working.ingredients[active].unit)||100}"></label><button type="button" class="outline" data-match-search>Search</button></div><p class="match-status">Choose the closest food, or mark an ingredient such as water or spices as nutritionally negligible.</p><button type="button" class="negligible" data-negligible>Mark as negligible</button><div class="match-results"></div>`}</section></div><div class="review-actions"><button type="button" class="outline" data-review-later>Finish later</button><button type="button" class="primary" data-save-ready ${done!==total?'disabled':''}>Save as planner ready</button></div></section>`);document.querySelector('[data-review-later]').onclick=()=>openRecipeDetail(source.id);document.querySelectorAll('[data-review-ingredient]').forEach(button=>button.onclick=()=>{active=Number(button.dataset.reviewIngredient);draw();runSearch()});document.querySelector('[data-match-search]')?.addEventListener('click',runSearch);document.querySelector('#matchQuery')?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();runSearch()}});document.querySelector('[data-negligible]')?.addEventListener('click',()=>{working.ingredients[active]={...working.ingredients[active],calories:0,protein:0,nutritionReviewed:true,nutritionSource:'Reviewed as negligible'};reviewed.add(active);active=working.ingredients.findIndex((_,index)=>!reviewed.has(index));draw()});document.querySelector('[data-save-ready]')?.addEventListener('click',async()=>{const nutrition=calculateNutrition(working.ingredients,working.servings),finished={...working,...nutrition,nutritionReady:true};state.customRecipes=state.customRecipes.map(item=>item.id===finished.id?finished:item);state.recipes=state.recipes.map(item=>item.id===finished.id?finished:item);state.reviews[finished.id]={...(state.reviews[finished.id]||{status:'Draft',rating:0,notes:''}),excluded:false};close();await save(`${finished.title} is ready to plan`);renderRecipes()})};const runSearch=async()=>{if(active<0)return;const query=document.querySelector('#matchQuery')?.value.trim(),status=document.querySelector('.match-status'),results=document.querySelector('.match-results');if(!query||query.length<2)return toast('Enter at least 2 characters');status.textContent='Searching USDA FoodData Central…';results.innerHTML='';try{const response=await fetch(`/api/usda/search?q=${encodeURIComponent(query)}`),payload=await apiPayload(response);if(!response.ok)throw Error(payload.error||'Search unavailable');status.textContent=payload.foods.length?'Choose the closest description. Values shown are per 100 g.':'No matches found. Try a simpler food name.';results.innerHTML=payload.foods.slice(0,8).map((food,index)=>`<button type="button" data-match-result="${index}"><span><strong>${esc(food.name)}</strong><small>${esc(food.brand||food.dataType)}</small></span><b>${food.calories} kcal<br>${food.protein}g protein</b><i>＋</i></button>`).join('');document.querySelectorAll('[data-match-result]').forEach(button=>button.onclick=()=>{const food=payload.foods[Number(button.dataset.matchResult)],amount=Math.max(1,Number(document.querySelector('#matchAmount').value)||100),factor=amount/100;working.ingredients[active]={...working.ingredients[active],quantity:amount,unit:'g',calories:Math.round(food.calories*factor),protein:Math.round(food.protein*factor*10)/10,nutritionReviewed:true,nutritionSource:'USDA FoodData Central',fdcId:food.fdcId};reviewed.add(active);active=working.ingredients.findIndex((_,index)=>!reviewed.has(index));draw()})}catch(error){status.textContent=error.message}};draw();if(active>=0)runSearch()}
function openOnlineRecipeSearch(){modal(`<p class="eyebrow">RECIPE DISCOVERY</p><h2 id="modalTitle">Find something new</h2><p class="dialog-copy">Search TheMealDB by meal name. Saved recipes remain local and start as drafts until you check their nutrition.</p><div class="provider-search"><input id="mealDbQuery" type="search" placeholder="Try chicken curry, salmon, pasta…"><button class="primary" type="button" data-mealdb-search>Search recipes</button></div><p class="provider-status">Free recipe discovery powered by TheMealDB.</p><div class="provider-results"></div>`);const search=async()=>{const query=document.querySelector('#mealDbQuery').value.trim(),status=document.querySelector('.provider-status'),results=document.querySelector('.provider-results');if(query.length<2)return toast('Enter at least 2 characters');status.textContent='Looking for recipes…';results.innerHTML='';try{const response=await fetch(`/api/recipes/search?q=${encodeURIComponent(query)}`),payload=await apiPayload(response);if(!response.ok)throw Error(payload.error||'Search unavailable');status.textContent=payload.recipes.length?`${payload.recipes.length} recipe${payload.recipes.length===1?'':'s'} found`:'No recipes found. Try a broader meal name.';results.innerHTML=payload.recipes.map((r,index)=>`<article><img src="${esc(r.image||fallbackImage)}" alt="${esc(r.title)}"><div><small>${esc([r.area,r.category].filter(Boolean).join(' · ')||'TheMealDB')}</small><strong>${esc(r.title)}</strong><span>${r.ingredients.length} ingredients</span></div><button type="button" data-save-online="${index}">${state.recipes.some(x=>x.id===r.id)?'Saved':'Save draft'}</button></article>`).join('');document.querySelectorAll('[data-save-online]').forEach(button=>button.onclick=async()=>{const found=payload.recipes[Number(button.dataset.saveOnline)];if(state.recipes.some(x=>x.id===found.id))return toast('This recipe is already saved');state.customRecipes.push(found);state.recipes.push(found);state.reviews[found.id]={status:'Draft',rating:0,notes:'',excluded:true};button.textContent='Saved';button.disabled=true;await save(`${found.title} saved as a draft`)})}catch(error){status.textContent=error.message}};document.querySelector('[data-mealdb-search]').onclick=search;document.querySelector('#mealDbQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search()}}}
function nutritionIngredients(text){return text.split('\n').map(line=>line.split('|').map(x=>x.trim())).filter(p=>p[0]&&Number(p[1])).map(([name,quantity,unit='whole',aisle='Other',calories='0',protein='0'])=>({name,quantity:Number(quantity),unit,aisle,calories:Number(calories)||0,protein:Number(protein)||0}))}
function openRecipeForm(existing=null){const ingredientText=existing?.ingredients?.map(i=>`${i.name} | ${i.quantity} | ${i.unit} | ${i.aisle} | ${i.calories||0} | ${i.protein||0}`).join('\n')||'',instructions=existing?.instructions?.join('\n')||'';modal(`<p class="eyebrow">${existing?'EDIT':'ADD'} PERSONAL RECIPE</p><h2 id="modalTitle">${existing?'Fine-tune your recipe':'Create a recipe'}</h2><p class="dialog-copy">Search USDA for nutrition, or enter ingredient totals from a food label. Savorly calculates the per-serving totals.</p><form id="recipeForm" class="recipe-form"><label class="wide">Recipe name<input name="title" value="${esc(existing?.title)}" required></label><label>Prep + cook time <small>(minutes)</small><input name="time" type="number" min="1" value="${existing?.time||30}" required></label><label>Servings<input name="servings" type="number" min="1" max="50" value="${existing?.servings||4}" required></label><label class="wide">Photo URL <small>(optional)</small><input name="image" type="url" value="${esc(existing?.image)}" placeholder="https://..."></label><section class="usda-lookup wide"><div><strong>USDA ingredient search</strong><small>Nutrition values come from FoodData Central</small></div><div class="usda-search"><input id="usdaQuery" type="search" placeholder="Try chicken breast, brown rice, Greek yogurt…"><label>Amount (g)<input id="usdaAmount" type="number" min="1" max="10000" value="100"></label><button type="button" class="outline" data-usda-search>Search</button></div><p class="usda-status">Enter the amount used in the full recipe, then choose the closest food.</p><div class="usda-results"></div></section><label class="wide">Ingredients <small>Name | quantity | unit | aisle | total calories | total protein</small><textarea name="ingredients" rows="8" placeholder="Chicken breast | 2 | lb | Meat | 1496 | 280&#10;Rice | 2 | cups | Pantry | 1360 | 26" required>${esc(ingredientText)}</textarea></label><div class="nutrition-preview wide"><span>Calculated per serving</span><strong id="calcCalories">0 kcal</strong><strong id="calcProtein">0g protein</strong></div><label class="wide">Instructions <small>One step per line</small><textarea name="instructions" rows="7" placeholder="Season and brown the chicken.&#10;Add rice and broth, then cover and simmer." required>${esc(instructions)}</textarea></label><label class="wide">Storage guidance<textarea name="storage" rows="2" placeholder="Refrigerate 3–4 days; freeze remaining portions.">${esc(existing?.storage)}</textarea></label><label class="check"><input name="batch" type="checkbox" ${existing?.batch?'checked':''}> This is a one-pot batch meal</label><button class="primary wide">${existing?'Save changes':'Add to my recipes'}</button></form>`);const form=document.querySelector('#recipeForm'),update=()=>{const ingredients=nutritionIngredients(form.elements.ingredients.value),servings=Math.max(1,Number(form.elements.servings.value)||1),calories=Math.round(ingredients.reduce((n,i)=>n+i.calories,0)/servings),protein=Math.round(ingredients.reduce((n,i)=>n+i.protein,0)/servings);document.querySelector('#calcCalories').textContent=`${calories} kcal`;document.querySelector('#calcProtein').textContent=`${protein}g protein`;return{ingredients,calories,protein}},search=async()=>{const query=document.querySelector('#usdaQuery').value.trim(),status=document.querySelector('.usda-status'),results=document.querySelector('.usda-results');if(query.length<2)return toast('Enter at least 2 characters');status.textContent='Searching USDA FoodData Central…';results.innerHTML='';try{const response=await fetch(`/api/usda/search?q=${encodeURIComponent(query)}`),payload=await apiPayload(response);if(!response.ok)throw Error(payload.error||'Search unavailable');status.textContent=payload.foods.length?`${payload.foods.length} matches · values shown per 100 g · ${payload.mode==='demo'?'Demo access':'Your API key'}`:'No matches found. Try a simpler food name.';results.innerHTML=payload.foods.map((food,index)=>`<button type="button" data-usda-result="${index}"><span><strong>${esc(food.name)}</strong><small>${esc(food.brand||food.dataType)} · per ${esc(food.basis)}</small></span><b>${food.calories} kcal<br>${food.protein}g protein</b><i>＋</i></button>`).join('');document.querySelectorAll('[data-usda-result]').forEach(button=>button.onclick=()=>{const food=payload.foods[Number(button.dataset.usdaResult)],amount=Math.max(1,Number(document.querySelector('#usdaAmount').value)||100),factor=amount/100,calories=Math.round(food.calories*factor),protein=Math.round(food.protein*factor*10)/10,line=`${food.name} | ${amount} | g | Other | ${calories} | ${protein}`;form.elements.ingredients.value+=(form.elements.ingredients.value.trim()?'\n':'')+line;update();button.classList.add('added');button.querySelector('i').textContent='✓';toast(`${amount} g ${food.name} added`)})}catch(error){status.textContent=error.message}};document.querySelector('[data-usda-search]').onclick=search;document.querySelector('#usdaQuery').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();search()}};form.elements.ingredients.addEventListener('input',update);form.elements.servings.addEventListener('input',update);update();form.onsubmit=async e=>{e.preventDefault();const d=new FormData(form),{ingredients,calories,protein}=update(),steps=d.get('instructions').split('\n').map(x=>x.trim()).filter(Boolean);if(!ingredients.length||!steps.length)return toast('Add at least one valid ingredient and instruction');if(!calories&&!protein)return toast('Add nutrition totals to your ingredient lines');const item={...(existing||{}),id:existing?.id||`custom-${crypto.randomUUID()}`,custom:true,title:d.get('title').trim(),time:Number(d.get('time')),difficulty:'Personal',calories,protein,servings:Number(d.get('servings')),image:d.get('image').trim()||fallbackImage,ingredients,instructions:steps,storage:d.get('storage').trim()||'Refrigerate for up to 3–4 days; freeze extra portions.',batch:d.has('batch'),batchDays:d.has('batch')?'3–5 meals':''};state.customRecipes=existing?state.customRecipes.map(r=>r.id===item.id?item:r):[...state.customRecipes,item];state.recipes=existing?state.recipes.map(r=>r.id===item.id?item:r):[...state.recipes,item];state.reviews[item.id]??={status:'Draft',rating:0,notes:''};if(existing?.imported)state.reviews[item.id]={...state.reviews[item.id],excluded:false};close();recipeFilter='mine';await save(existing?'Recipe updated and ready to plan':'Recipe added to your library');renderRecipes()}}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1800)}
load().catch(()=>app.innerHTML='<section class="empty-state"><h2>We could not load your planner.</h2><p>Refresh the page to try again.</p></section>');
